-- ========================================================
local DreamlandUtils = import('Game.UI.FightReady.UIDreamland.DreamlandUtils')


--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

---@type DreamSpaceStates
local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Physics = CS.UnityEngine.Physics
local Collider = CS.UnityEngine.Collider

--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils
local LuaParameters = CS.Engine.Modules.LuaParameters

local ElectricalApplianceBase = CS.ElectricalSystem.ElectricalApplianceBase

-- ========================================================


local State = 
{
    Off = 0,  
    On  = 1,   
}

-- ========================================================


function CollideTrigger:__init()
    self.controller = nil
    self.co = nil   -- 发送携程请求

    self.WhenTriggerEnter = nil -- callback 函数指针
end


function CollideTrigger:__delete()
    self.co = nil
end



function CollideTrigger:Start()
    KTool.SetActive(self.controller.gameObject, true);
    -- ==============================
    -- 绑定 OnTriggerEnter() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnTriggerEnterAction = function(behaviourAction,other_)
            self:OnTriggerEnter(other_)
        end
    end

    self.collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
    assert( self.collider )


    -- 启动阶段, 本 collider 被隐藏
    self:SetActive( false )


    -- 只有当关联电器被触发后, 本 collider 才会被启动
    self.state = State.Off 
    self.eBase = KTool.GetComponent(self.controller.gameObject, typeof(ElectricalApplianceBase))
    self.eBase:OnHandleElectrifiedState( '+', function( brain_ ) 
        if ( self.state == State.Off ) then
            self.state = State.On
            self:SetActive( true )
        end
    end ) 

end




function CollideTrigger:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end



-- ===============================================================


function CollideTrigger:SetActive(isActive_)
    self.collider.enabled = isActive_
end




function CollideTrigger:OnTriggerEnter(other_)
    if self.WhenTriggerEnter ~= nil then 
        self.WhenTriggerEnter(other_) -- 函数指针
    end 
end





return CollideTrigger
